// Every function that takes `$` lives in this file: the engine follows `$`
// only into functions declared beside the hooks. Pure helpers are in ./lib.
// The status line is this mod's alone: usage shows nowhere else but its pane.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Meter, Reading } from '../types'
import {
  BAR_HEIGHT,
  BAR_WIDTH,
  CLAUDE_STALE_MS,
  KIND_LABELS,
  barSvg,
  barText,
  clockTime,
  isReading,
  levelColor,
  statusSegment,
  viewOf,
} from './lib'
import type { MeterView } from './lib'
import { AMBER } from './shared/colors'
import { LIMIT, WARN } from './shared/glyphs'
import { rtl } from './shared/rtl'
import { oneLine } from './shared/text'
import { formatAge, formatResetIn } from './shared/time'

const claude = atom({ plugin: 'usage', key: 'claude' } as const, null)

const THRESHOLDS = [95, 80]
/** How often the status line is judged again: a reset that passed, a reading grown stale. */
const TICK_MS = 15_000

const PANE = 'usage'
const SHOW = { id: PANE, title: 'צריכה', focus: true as const, closeOnEscape: true as const, rows: 14, columns: 46 }

/** The status line last pinned, so a tick that changes nothing pins nothing. */
let lastStatus: string | undefined

/**
 * Shows each window's highest crossed threshold once per reset period; the lower
 * ones count as shown with it, so a percent that falls back does not toast again.
 */
async function toastCrossings($: EngineInterface, meters: Meter[]) {
  const view = viewOf({ meters, at: 0, isLive: true }, await $.clock.now())
  const shown = ((await $.store.get('toasted')) as string[] | undefined) ?? []
  const fresh: string[] = []
  meters.forEach((meter, i) => {
    // A window past its reset is over: its percent is not this period's.
    if (view?.meters[i]?.percent === null) return
    const crossed = THRESHOLDS.find(t => meter.percentUsed >= t)
    if (crossed === undefined) return
    const idOf = (t: number) => `Claude:${meter.kind}:${meter.resetsAt ?? ''}:${t}`
    if (THRESHOLDS.some(t => t >= crossed && shown.includes(idOf(t)))) return
    fresh.push(...THRESHOLDS.filter(t => t <= crossed).map(idOf))
    $.ui.toast(`Claude: ניצלת ${Math.round(meter.percentUsed)}% מחלון ה-${KIND_LABELS[meter.kind] ?? meter.kind}`)
  })
  if (fresh.length > 0) await $.store.set('toasted', [...shown, ...fresh].slice(-50))
}

/** The status line as of now: resets that passed show as "—", a stale reading its age. */
async function showStatus($: EngineInterface) {
  const now = await $.clock.now()
  const text = statusSegment('Claude', viewOf(await read($, claude), now, CLAUDE_STALE_MS), now, true)
  if (text === lastStatus) return
  lastStatus = text
  $.ui.status(text)
}

async function setClaude($: EngineInterface, meters: Meter[]) {
  const reading: Reading = { meters, at: await $.clock.now(), isLive: true }
  await update($, claude, () => reading)
  await $.store.set('claude', reading)
  await toastCrossings($, meters)
  await showStatus($)
}

/**
 * The engine's reading from the session's last response; empty until the first.
 * Only right after a response: it stamps the reading as taken now.
 */
async function refreshClaude($: EngineInterface) {
  const { rateLimits } = await $.session.usage()
  if (rateLimits.length > 0) {
    await setClaude($, rateLimits.map(({ kind, percentUsed, resetsAt }) => ({ kind, percentUsed, resetsAt })))
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    // State and store outlive the code that wrote them: a value of another shape goes.
    await update($, claude, r => (isReading(r) ? r : null))
    // The last reading, with the time it was taken: `$.session.usage()` may hand back
    // a resumed session's last response, which is not a reading taken now.
    const stored = await $.store.get('claude')
    if (isReading(stored)) await update($, claude, () => ({ ...stored, isLive: false }))
    lastStatus = undefined
    await showStatus($)
    // Time passes without a reading: a reset passes, a reading grows stale.
    $.clock.every(TICK_MS, async () => {
      await showStatus($)
      $.ui.invalidate('ui.render')
    })
    return next(e)
  })

  // `/usage` is a built-in command: its name cannot be registered, only hooked.
  on('command.run', { command: 'usage' }, async $ => {
    await $.ui.open(SHOW)
    return { text: 'פאנל הצריכה פתוח.' }
  })

  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('rateLimits') && e.rateLimits.length > 0) {
      await setClaude($, e.rateLimits.map(({ kind, percentUsed, resetsAt }) => ({ kind, percentUsed, resetsAt })))
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (!e.agentId) {
      // A measure fires only when a percent changed: an unchanged reading is fresh too.
      await refreshClaude($)
    }
    return next(e)
  })

  // The layout reads right to left: rows are `row-reverse`, columns hug the right
  // edge, and Hebrew runs are isolated as RTL (`rtl`).
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const table = $.ui.resolve(e)
    const { Box, Text } = table
    // A surface's table may carry an element it then refuses: decide by the surface.
    const Svg = (e.surface === 'desktop' || e.surface === 'vscode') && 'Svg' in table ? table.Svg : undefined
    const now = await $.clock.now()
    const claudeView = viewOf(await read($, claude), now, CLAUDE_STALE_MS)

    const resetLine = (meter: MeterView) => {
      if (meter.resetMs === undefined) return ''
      const left = formatResetIn(new Date(meter.resetMs).toISOString(), now)
      return meter.kind === 'five_hour' ? `${left} · ${clockTime(meter.resetMs)}` : left
    }

    const meterRow = (meter: MeterView) => (
      <Box key={`claude-${meter.kind}`} flexDirection="column" alignItems="flex-end">
        <Box flexDirection="row-reverse" gap={1}>
          <Text>{rtl(oneLine(KIND_LABELS[meter.kind] ?? meter.kind, 30))}</Text>
          {meter.percent === null ? (
            <Text dimColor>{rtl('התאפס')}</Text>
          ) : (
            <Text bold color={levelColor(meter.level === 'reset' ? 'ok' : meter.level)}>
              {`${Math.round(meter.percent)}%${meter.level === 'max' ? ` ${LIMIT}` : meter.level === 'warn' ? ` ${WARN}` : ''}`}
            </Text>
          )}
          {meter.percent === null ? null : <Text dimColor>{rtl(resetLine(meter))}</Text>}
        </Box>
        {meter.percent === null ? null : Svg ? (
          <Svg
            source={barSvg(meter.percent)}
            alt={`Claude ${meter.kind} ${Math.round(meter.percent)}%`}
            width={BAR_WIDTH}
            height={BAR_HEIGHT}
          />
        ) : (
          <Text color={levelColor(meter.level === 'reset' ? 'ok' : meter.level)}>{barText(meter.percent)}</Text>
        )}
      </Box>
    )

    return (
      <Box flexDirection="column" alignItems="flex-end" gap={1}>
        <Box flexDirection="column" alignItems="flex-end">
          <Box flexDirection="row-reverse" gap={1}>
            <Text bold>Claude</Text>
            {claudeView?.isStale ? <Text color={AMBER}>{rtl(`${WARN} ישן · ${formatAge(claudeView.at, now)}`)}</Text> : null}
          </Box>
          {claudeView && claudeView.meters.length > 0 ? (
            claudeView.meters.map(meterRow)
          ) : (
            <Text dimColor>{rtl('אין עדיין קריאה — תופיע אחרי התשובה הראשונה')}</Text>
          )}
        </Box>
      </Box>
    )
  })
}

