// Pure helpers: no `$`, so the tests import them directly.
import type { Meter, Reading } from '../types'
import { AMBER, GREEN, RED } from './shared/colors'
import { LIMIT, WARN } from './shared/glyphs'

export const KIND_LABELS: Record<string, string> = { five_hour: '5 שעות', seven_day: 'שבועי', spend_limit: 'מגבלת הוצאה' }
const SHORT_LABELS: Record<string, string> = { five_hour: '5h', seven_day: '7d', spend_limit: '$' }

/** Claude's limits are the account's: other sessions use them too, so a reading this old may be off. */
export const CLAUDE_STALE_MS = 30 * 60_000

const MINUTE = 60_000
const DAY = 24 * 60 * MINUTE

/** A stored value in a reading's shape, or not: state and store outlive the code that wrote them. */
export function isReading(value: unknown): value is Reading {
  if (value === null || typeof value !== 'object') return false
  const r = value as Partial<Reading>
  return (
    typeof r.at === 'number' &&
    Array.isArray(r.meters) &&
    r.meters.every(m => m !== null && typeof m === 'object' && typeof m.kind === 'string' && typeof m.percentUsed === 'number')
  )
}

// ── what is shown ────────────────────────────────────────────────────────

/** ok below 80%, ⚠ from 80%, ⛔ from 95%. */
export type Level = 'ok' | 'warn' | 'max'

export function levelOf(percent: number): Level {
  if (percent >= 95) return 'max'
  if (percent >= 80) return 'warn'
  return 'ok'
}

export function levelColor(level: Level): string {
  return level === 'max' ? RED : level === 'warn' ? AMBER : GREEN
}

/** A window as shown now: one past its reset has no percent (its old one is over). */
export type MeterView = { kind: string; percent: number | null; level: Level | 'reset'; resetMs?: number }

/** A reading as shown now; `isStale` only when it is old enough to be off. */
export type ReadingView = { meters: MeterView[]; at: number; isStale: boolean; ageMs: number }

/** What to show of a reading at `nowMs`: resets that passed are applied, and its age judged. */
export function viewOf(reading: Reading | null, nowMs: number, staleAfterMs?: number): ReadingView | null {
  if (!reading) return null
  const ageMs = Math.max(0, nowMs - reading.at)
  const meters = reading.meters.map((meter): MeterView => {
    const resetMs = meter.resetsAt ? Date.parse(meter.resetsAt) : Number.NaN
    const hasReset = !Number.isNaN(resetMs) && resetMs <= nowMs
    return {
      kind: meter.kind,
      percent: hasReset ? null : meter.percentUsed,
      level: hasReset ? 'reset' : levelOf(meter.percentUsed),
      resetMs: Number.isNaN(resetMs) || hasReset ? undefined : resetMs,
    }
  })
  return { meters, at: reading.at, isStale: staleAfterMs !== undefined && ageMs >= staleAfterMs, ageMs }
}

/** "40m" / "2h" / "3d": an age or a span, short enough for the status line. */
export function formatSpanShort(ms: number): string {
  const minutes = Math.max(0, Math.floor(ms / MINUTE))
  if (minutes < 60) return `${minutes}m`
  if (minutes < 24 * 60) return `${Math.floor(minutes / 60)}h`
  return `${Math.floor(minutes / (24 * 60))}d`
}

/** "14:30" in local time. */
export function clockTime(ms: number): string {
  const at = new Date(ms)
  return `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`
}

/**
 * When a window resets, for the status line: the five-hour window by the clock
 * ("↻14:30"), a longer one by what is left ("↻3d", under a day "↻20h").
 */
export function resetMark(meter: MeterView, nowMs: number): string {
  if (meter.resetMs === undefined) return ''
  if (meter.kind === 'five_hour') return `↻${clockTime(meter.resetMs)}`
  const left = meter.resetMs - nowMs
  return `↻${left >= DAY ? `${Math.floor(left / DAY)}d` : formatSpanShort(Math.max(left, MINUTE))}`
}

/**
 * "Claude 5h 83% ⚠ ↻14:30 · 7d 9% ↻3d" for the status line: ⚠ from 80%, ⛔ from
 * 95%, "—" for a window past its reset, "⌛2h" when the reading is stale.
 * `withResets` adds when each window resets.
 */
export function statusSegment(name: string, view: ReadingView | null, nowMs: number, withResets = false): string {
  if (!view || view.meters.length === 0) return `${name} —`
  const parts = view.meters.map(meter => {
    const label = SHORT_LABELS[meter.kind] ?? meter.kind
    if (meter.percent === null) return `${label} —`
    const mark = meter.level === 'max' ? ` ${LIMIT}` : meter.level === 'warn' ? ` ${WARN}` : ''
    const reset = withResets ? resetMark(meter, nowMs) : ''
    return `${label} ${Math.round(meter.percent)}%${mark}${reset ? ` ${reset}` : ''}`
  })
  return `${name} ${parts.join(' · ')}${view.isStale ? ` ⌛${formatSpanShort(view.ageMs)}` : ''}`
}

/** A meter bar in text that fills from the right, as a Hebrew reader expects. */
export function barText(percent: number, width = 20): string {
  const filled = Math.max(0, Math.min(width, Math.round((percent / 100) * width)))
  return '░'.repeat(width - filled) + '█'.repeat(filled)
}

export const BAR_WIDTH = 260
export const BAR_HEIGHT = 10

/** A meter bar as SVG that fills from the right; a spend limit past 100% fills it whole. */
export function barSvg(percent: number): string {
  const width = (Math.max(0, Math.min(100, percent)) * BAR_WIDTH) / 100
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${BAR_WIDTH}" height="${BAR_HEIGHT}" viewBox="0 0 ${BAR_WIDTH} ${BAR_HEIGHT}">` +
    `<rect width="${BAR_WIDTH}" height="${BAR_HEIGHT}" rx="5" fill="#8a8a8a" fill-opacity="0.25"/>` +
    `<rect x="${(BAR_WIDTH - width).toFixed(1)}" width="${width.toFixed(1)}" height="${BAR_HEIGHT}" rx="5" fill="${levelColor(levelOf(percent))}"/>` +
    '</svg>'
  )
}

