export const RED = '#D9534F'
export const AMBER = '#D9A030'
export const GREEN = '#3FA672'
export const ACCENT = '#4F8EF7'

/** What a line means, and so its colour; `muted` draws dim, with no colour. */
export type Tone = 'ok' | 'needs-you' | 'failed' | 'codex' | 'muted'

export function toneColor(tone: Tone): string | undefined {
  return { ok: GREEN, 'needs-you': AMBER, failed: RED, codex: ACCENT, muted: undefined }[tone]
