// Long text in a pane: a summary of a few rows, and the whole of it split into
// blocks a Text, Markdown or Code element accepts (at most 10000 characters,
// tab and newline the only control characters), and the blocks into pages (a
// tree past 100000 characters of text is refused whole).

export const TEXT_MAX = 10000

const ANSI = /\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[@-_]/g
const CONTROL = /[\x00-\x08\x0b-\x1f\x7f-\x9f]/g

/** Text an element accepts: no ANSI escapes, LF line ends, no control characters but tab and newline. */
export function cleanText(text: string): string {
  return text.replace(ANSI, '').replace(/\r\n?/g, '\n').replace(CONTROL, '')
}

/** One line of at most `max` characters, for a pane title or a label. */
export function oneLine(text: string, max = 60): string {
  const line = cleanText(text).replace(/\s+/g, ' ').trim()
  return line.length > max ? `${cutAt(line, max - 1)}…` : line
}

/** Text cleaned and held to `max` characters, for one element of a pane. */
export function bounded(text: string, max = 2000): string {
  const clean = cleanText(text)
  return clean.length > max ? `${cutAt(clean, max - 1)}…` : clean
}

export type Summary = { text: string; isWhole: boolean }

const SKIPPED = /^\s*(#{1,6}\s|(?:-{3,}|\*{3,}|_{3,})\s*$|(?:`{3,}|~{3,})\S*\s*$)/

/**
 * The text's first paragraph, in at most `rows` rows of `columns` (headings,
 * rules and fence lines before it skipped); `isWhole` when that is all of it.
 */
export function summarize(text: string, options: { rows?: number; columns?: number } = {}): Summary {
  const rows = options.rows ?? 3
  const width = Math.min(1000, Math.max(10, (options.columns ?? 80) - 2))
  const whole = cleanText(text).trim()
  if (!whole) return { text: '', isWhole: true }
  const lines = whole.split('\n')
  let start = 0
  while (start < lines.length && (lines[start]?.trim() === '' || SKIPPED.test(lines[start] ?? ''))) start++
  const paragraph: string[] = []
  for (const line of lines.slice(start)) {
    if (line.trim() === '') break
    if (!SKIPPED.test(line)) paragraph.push(line.trimEnd())
  }
  const picked: string[] = []
  let left = rows
  for (const line of paragraph) {
    if (left <= 0) break
    const cost = Math.max(1, Math.ceil(line.length / width))
    if (cost <= left) {
      picked.push(line)
      left -= cost
    } else {
      picked.push(`${cutAt(line, left * width - 1)}…`)
      left = 0
    }
  }
  const summary = picked.join('\n')
  return { text: summary, isWhole: summary === whole }
}

/** Cuts at `at` code units, never between the halves of a surrogate pair. */
function cutAt(text: string, at: number): string {
  if (at <= 0) return ''
  if (at >= text.length) return text
  const code = text.charCodeAt(at - 1)
  return text.slice(0, code >= 0xd800 && code <= 0xdbff ? at - 1 : at)
}

/** A line longer than `limit` as pieces of at most `limit`. */
export function cutLine(line: string, limit: number): string[] {
  const pieces: string[] = []
  let rest = line
  while (rest.length > limit) {
    const piece = cutAt(rest, limit)
    pieces.push(piece)
    rest = rest.slice(piece.length)
  }
  pieces.push(rest)
  return pieces
}

/** Room kept in each block for a fence closed at its end and reopened at the next one's start. */
const FENCE_ROOM = 200
const FENCE_OPEN = /^\s*(`{3,}|~{3,})(.*)$/

/**
 * Markdown as blocks of at most `max` characters: split between paragraphs where
 * it can, between lines where it must; a code fence cut in two is closed at the
 * end of one block and reopened at the start of the next.
 */
export function splitMarkdown(text: string, max = TEXT_MAX): string[] {
  const whole = cleanText(text)
  if (whole.length <= max) return whole.trim() ? [whole] : []
  const blocks: string[] = []
  let lines: string[] = []
  let size = 0
  let fence: { mark: string; open: string } | null = null
  let lastBreak = -1
  const measure = () => {
    size = lines.reduce((sum, line, i) => sum + line.length + (i > 0 ? 1 : 0), 0)
  }
  const fits = (line: string) => size + (lines.length > 0 ? 1 : 0) + line.length + (fence ? fence.mark.length + 1 : 0) <= max
  for (const raw of whole.split('\n')) {
    for (const line of cutLine(raw, max - 2 * FENCE_ROOM)) {
      while (!fits(line) && lines.length > 0) {
        if (lastBreak > 0) {
          // Between paragraphs, outside any fence: the rest moves on whole.
          blocks.push(lines.slice(0, lastBreak).join('\n'))
          lines = lines.slice(lastBreak + 1)
        } else {
          blocks.push(lines.join('\n') + (fence ? `\n${fence.mark}` : ''))
          lines = fence ? [fence.open] : []
        }
        lastBreak = -1
        measure()
      }
      if (!fence && line.trim() === '') lastBreak = lines.length
      const opening: RegExpExecArray | null | undefined = fence ? undefined : FENCE_OPEN.exec(line)
      if (opening) {
        const mark: string = opening[1] ?? '```'
        fence = { mark, open: `${mark}${oneLine(opening[2] ?? '', FENCE_ROOM / 2 - mark.length)}` }
      } else if (fence && line.trim().startsWith(fence.mark) && /^(`+|~+)$/.test(line.trim())) {
        fence = null
      }
      size += (lines.length > 0 ? 1 : 0) + line.length
      lines.push(line)
    }
  }
  if (lines.some(line => line.trim() !== '')) blocks.push(lines.join('\n'))
  return blocks.filter(block => block.trim() !== '')
}

/** Plain text (a command's output) as blocks of at most `max` characters, split between lines. */
export function splitPlain(text: string, max = TEXT_MAX): string[] {
  const whole = cleanText(text)
  if (whole.length <= max) return whole ? [whole] : []
  const blocks: string[] = []
  let lines: string[] = []
  let size = 0
  for (const raw of whole.split('\n')) {
    for (const line of cutLine(raw, max)) {
      const cost = (lines.length > 0 ? 1 : 0) + line.length
      if (size + cost > max && lines.length > 0) {
        blocks.push(lines.join('\n'))
        lines = []
        size = 0
      }
      size += (lines.length > 0 ? 1 : 0) + line.length
      lines.push(line)
    }
  }
  if (lines.length > 0) blocks.push(lines.join('\n'))
  return blocks.filter(block => block.length > 0)
}

/** How much text one drawn tree may hold: the engine refuses a tree past 100000 characters. */
export const PAGE_MAX = 90000

/** Blocks as pages, each within `budget` characters, so one page is one tree the engine draws. */
export function pageBlocks(blocks: readonly string[], budget = PAGE_MAX): string[][] {
  const pages: string[][] = []
  let page: string[] = []
  let size = 0
  for (const block of blocks) {
    if (page.length > 0 && size + block.length > budget) {
      pages.push(page)
      page = []
      size = 0
    }
    page.push(block)
    size += block.length
  }
  if (page.length > 0) pages.push(page)
  return pages
}

/**
 * One line of at most `max` characters with its middle cut out ("cock…pit"), for a
 * name whose start and end both say something, such as a folder.
 */
export function middleTruncate(text: string, max: number): string {
  const line = cleanText(text).replace(/\s+/g, ' ').trim()
  if (line.length <= max) return line
  if (max <= 0) return ''
  if (max === 1) return '…'
  const head = cutAt(line, Math.ceil((max - 1) / 2))
  const tailLength = Math.floor((max - 1) / 2)
  let tail = tailLength > 0 ? line.slice(line.length - tailLength) : ''
  // Never begin on the second half of a surrogate pair.
  const first = tail.charCodeAt(0)
  if (first >= 0xdc00 && first <= 0xdfff) tail = tail.slice(1)
  return `${head}…${tail}`
}

