/** "בעוד 2:05 שע'" / "בעוד 3 ימים" — relative, so no time zone is needed. */
export function formatResetIn(resetsAt: string | undefined, nowMs: number): string {
  if (!resetsAt) return ''
  const left = Date.parse(resetsAt) - nowMs
  if (Number.isNaN(left)) return ''
  if (left <= 0) return 'התאפס'
  const minutes = Math.ceil(left / 60_000)
  if (minutes < 60) return `איפוס בעוד ${minutes} דק'`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `איפוס בעוד ${hours}:${String(minutes % 60).padStart(2, '0')} שע'`
  const days = Math.floor(hours / 24)
  return `איפוס בעוד ${days} ${days === 1 ? 'יום' : 'ימים'} ו-${hours % 24} שע'`
}

export function formatAge(atMs: number, nowMs: number): string {
  const minutes = Math.floor((nowMs - atMs) / 60_000)
  if (minutes < 1) return 'עכשיו'
  if (minutes < 60) return `לפני ${minutes} דק'`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `לפני ${hours} שע'`
  return `לפני ${Math.floor(hours / 24)} ימים`
}

