/** One rate-limit window: `five_hour`, `seven_day`, or another window's name. */
export type Meter = { kind: string; percentUsed: number; resetsAt?: string }

/**
 * A reading of Claude's windows, as read: `at` is when it was taken (ms).
 * Whether a window has reset or the reading is stale is judged when it is shown.
 */
export type Reading = { meters: Meter[]; at: number; isLive: boolean }

declare module 'claude-code' {
  interface PluginState {
    usage: {
      claude: Reading | null
    }
  }
}
